-- ============================================================================
-- TRANSPORT : lignes pro (bus/ferry/7-places) dans le module Covoiturage (onglet
-- « Lignes »). Ecrit transport_lines + transport_recurrences. Genere depuis
-- prospection/transport_dakar_regions_senegal.csv (miroir de l'importateur onglet 3).
-- Idempotent (upsert sur operator+origin_city+destinations+vehicle_type ; recurrences
-- remplacees). Annuaire public, aucun vendor_id.
-- ============================================================================

on conflict (operator, origin_city, destinations, vehicle_type) do update set
  page_name=excluded.page_name, page_type=excluded.page_type, origin_gare=excluded.origin_gare, origin_address=excluded.origin_address, origin_quartier=excluded.origin_quartier, origin_region=excluded.origin_region, destination_main=excluded.destination_main, arrival_gare=excluded.arrival_gare, arrival_address=excluded.arrival_address, phone=excluded.phone, phones_all=excluded.phones_all, whatsapp=excluded.whatsapp, email=excluded.email, url_facebook=excluded.url_facebook, url_site=excluded.url_site, url_group_facebook=excluded.url_group_facebook, price_fcfa=excluded.price_fcfa, price_vip_fcfa=excluded.price_vip_fcfa, price_child_fcfa=excluded.price_child_fcfa, price_luggage=excluded.price_luggage, duration=excluded.duration, seats=excluded.seats, climatise=excluded.climatise, escales=excluded.escales, services=excluded.services, reservation=excluded.reservation, luggage_included=excluded.luggage_included, reservation_mode=excluded.reservation_mode, reservation_delay=excluded.reservation_delay, horaire_depart_raw=excluded.horaire_depart_raw, horaire_arrivee_raw=excluded.horaire_arrivee_raw, notes=excluded.notes, lat=excluded.lat, lng=excluded.lng, source=excluded.source, collected_at=excluded.collected_at, active=true, updated_at=now();

drop table if exists _trec;
create temp table _trec(operator text, origin_city text, destinations text, vehicle_type text, kind text, frequence_raw text, jours_raw text, days_of_week text[], excluded_days text[], departure_times text[], arrival_times text[], special_label text);

-- Remplace les recurrences existantes de ces lignes (idempotent), puis insere.
delete from public.transport_recurrences r using public.transport_lines l
 where r.line_id=l.id and (l.operator,l.origin_city,l.destinations,l.vehicle_type) in (select operator,origin_city,destinations,vehicle_type from _trec);

select l.id,t.kind,t.frequence_raw,t.jours_raw,t.days_of_week,t.excluded_days,t.departure_times,t.arrival_times,t.special_label
  from _trec t join public.transport_lines l on l.operator=t.operator and l.origin_city=t.origin_city and l.destinations=t.destinations and l.vehicle_type=t.vehicle_type;

select 'lignes' as type, count(*) from public.transport_lines union all select 'recurrences', count(*) from public.transport_recurrences;
